'use client'

import * as React from 'react'
import { useTranslations } from 'next-intl'
import { Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import { z } from 'zod'

import { Button, Input, Label, Tabs, TabsList, TabsTrigger, TabsContent } from '@ihui/ui-react'
import { sendCode, resetPassword } from '@ihui/api-client'
import { PasswordInput, PasswordStrengthIndicator } from '@/components/login'
import { useLoginDialogStore } from '@/stores/login-dialog'

const phoneRegex = /^1[3-9]\d{9}$/
const emailSchema = z.string().email()

/**
 * 找回密码：支持「手机验证码」与「邮箱验证码」两种重置方式。
 */
export function ForgotPasswordForm() {
  const t = useTranslations('auth')
  const [method, setMethod] = React.useState<'phone' | 'email'>('phone')

  const [phone, setPhone] = React.useState('')
  const [email, setEmail] = React.useState('')
  const [code, setCode] = React.useState('')
  const [newPassword, setNewPassword] = React.useState('')
  const [confirmPassword, setConfirmPassword] = React.useState('')

  const [submitting, setSubmitting] = React.useState(false)
  const [sending, setSending] = React.useState(false)
  const [countdown, setCountdown] = React.useState(0)
  const [error, setError] = React.useState<string | null>(null)

  React.useEffect(() => {
    if (countdown <= 0) return
    const timer = setTimeout(() => setCountdown((c) => c - 1), 1000)
    return () => clearTimeout(timer)
  }, [countdown])

  const target = method === 'phone' ? phone : email

  const handleSendCode = async () => {
    setError(null)
    if (method === 'phone' && !phoneRegex.test(phone)) {
      setError(t('invalidPhone'))
      return
    }
    if (method === 'email' && !emailSchema.safeParse(email).success) {
      setError(t('invalidEmail'))
      return
    }
    setSending(true)
    try {
      const r = await sendCode(method, target, 'reset')
      if (!r.success) {
        setError(r.error || t('registerFailed'))
        return
      }
      toast.success(t('codeSent'))
      setCountdown(60)
    } catch {
      setError(t('registerFailed'))
    } finally {
      setSending(false)
    }
  }

  const handleReset = async () => {
    setError(null)
    if (!code) return setError(t('enterCode'))
    if (newPassword.length < 6) return setError(t('invalidPassword'))
    if (newPassword !== confirmPassword) return setError(t('passwordMismatch'))
    setSubmitting(true)
    try {
      const r = await resetPassword({ method, target, code, newPassword })
      if (!r.success) {
        setError(r.error || t('registerFailed'))
        return
      }
      toast.success(t('resetSuccess'))
      useLoginDialogStore.getState().open('login')
    } catch {
      setError(t('registerFailed'))
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <div className="space-y-4">
      <Tabs
        value={method}
        onValueChange={(v) => {
          setMethod(v as typeof method)
          setError(null)
        }}
      >
        <TabsList className="grid w-full grid-cols-2">
          <TabsTrigger value="phone">{t('phone')}</TabsTrigger>
          <TabsTrigger value="email">{t('email')}</TabsTrigger>
        </TabsList>

        <TabsContent value="phone" className="pt-4">
          <Input
            type="tel"
            autoComplete="tel"
            placeholder={t('enterPhone')}
            className="h-10"
            value={phone}
            onChange={(e) => setPhone(e.target.value)}
          />
        </TabsContent>
        <TabsContent value="email" className="pt-4">
          <Input
            type="email"
            autoComplete="email"
            placeholder={t('emailPlaceholder')}
            className="h-10"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
          />
        </TabsContent>
      </Tabs>

      {error && (
        <div className="rounded-md bg-destructive/10 px-3 py-2 text-sm text-destructive">
          {error}
        </div>
      )}

      <div className="space-y-1.5">
        <Label htmlFor="fp-code">{t('code')}</Label>
        <div className="flex gap-2">
          <Input
            id="fp-code"
            inputMode="numeric"
            placeholder={t('enterCode')}
            className="h-10 flex-1"
            value={code}
            onChange={(e) => setCode(e.target.value)}
          />
          <Button
            type="button"
            variant="outline"
            className="h-10 shrink-0"
            disabled={sending || countdown > 0}
            onClick={handleSendCode}
          >
            {countdown > 0 ? t('resendCode', { seconds: countdown }) : t('sendCode')}
          </Button>
        </div>
      </div>

      <div className="space-y-1.5">
        <Label htmlFor="fp-new">{t('newPassword')}</Label>
        <PasswordInput
          id="fp-new"
          autoComplete="new-password"
          placeholder={t('enterNewPassword')}
          className="h-10"
          value={newPassword}
          onChange={(e) => setNewPassword(e.target.value)}
        />
        <PasswordStrengthIndicator password={newPassword} />
      </div>

      <div className="space-y-1.5">
        <Label htmlFor="fp-confirm">{t('confirmPassword')}</Label>
        <PasswordInput
          id="fp-confirm"
          autoComplete="new-password"
          placeholder={t('enterNewPassword')}
          className="h-10"
          value={confirmPassword}
          onChange={(e) => setConfirmPassword(e.target.value)}
        />
      </div>

      <Button type="button" className="h-10 w-full" disabled={submitting} onClick={handleReset}>
        {submitting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
        {t('resetPassword')}
      </Button>
    </div>
  )
}
